(async()=>{try{const response=await fetch('/api/account/',{cache:'no-store'});if(response.redirected||response.status===401||response.status===403||!response.headers.get('content-type')?.includes('application/json')){location.replace('/entrar');return}if(!response.ok)throw Error('Conexão indisponível');const account=await response.json();window.STUDY_ACCOUNT=account;window.STUDY_KEY='trilha-account-'+account.user.id;if(account.progress&&!localStorage.getItem(window.STUDY_KEY+"-pending"))localStorage.setItem(window.STUDY_KEY,JSON.stringify(account.progress));await Promise.all(['data','program','careers-data','quiz-bank','career-quiz-bank','careers','expansion','video-catalog','career-videos','curriculum-expansion','videos','quiz','learning-data','learning-media','learning','courses-data','course-labs','languages-data','language-videos','course-expansion-data','course-checks-data','languages','course-workbooks','courses','strategy-library','app','focus','account','support','support-audio','admins','notifications','appearance','password-admin','users-admin','dialogs','screen-dim'].map(file=>new Promise((resolve,reject)=>{const s=document.createElement('script');s.async=false;s.src=file+'.js?v=24';s.onload=resolve;s.onerror=reject;document.body.append(s)})));if(localStorage.getItem(window.STUDY_KEY+"-pending"))window.queueAccountProgress();document.body.classList.remove("booting");document.getElementById("app-loading")?.remove()}catch{document.body.innerHTML='<main style="padding:40px;font-family:Arial"><h1>Não foi possível carregar seus estudos.</h1><p>Verifique sua conexão e tente novamente.</p><button onclick="location.reload()">Tentar novamente</button></main>'}})();
